import "forge-std/Test.sol";
import "../src/0x0cbe050f75bc8f8c2d6c0d249fea125fd6e1acc9.sol";

contract CallerTimestampTest is Test {
    Caller public caller;
    address public constant TEST_ADDRESS = address(0xABCD);

    function setUp() public {
        caller = new Caller();
    }

    function test_MinerCanManipulateTimestamp() public {
        // Set two arbitrary timestamps to simulate miner manipulation
        uint256 timestampepoch1 = block.timestamp + 100 seconds;
        uint256 timestampepoch2 = block.timestamp + 300 seconds;

        // Make first call with manipulated timestamp
        vm.warp(timestampepoch1);
        vm.recordLogs();
        caller.callAddress(TEST_ADDRESS);

        Vm.Log[] memory logs = vm.getRecordedLogs();

        // Extract timestamp from event
        uint256 timestampEvent1 = abi.decode(logs[0].data, (uint256));
        assertEq(timestampEvent1, timestampepoch1, "First call timestamp mismatch");

        // Make second call with different manipulated timestamp
        vm.warp(timestampepoch2);
        vm.recordLogs();
        caller.callAddress(TEST_ADDRESS);

        logs = vm.getRecordedLogs();

        // Extract timestamp from event
        uint256 timestampEvent2 = abi.decode(logs[0].data, (uint256));
        assertEq(timestampEvent2, timestampepoch2, "Second call timestamp mismatch");
    }
}
